-- One BMO's line handed to another person's BMO, or the chat one opened into that person's room
-- (docs/relays.md): who sent it, who received it, the room it was said in, the line, and what came of it.
CREATE TABLE "relays" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "from_agent" text NOT NULL,
  "to_agent" text NOT NULL,
  "chat_id" bigint NOT NULL,
  "kind" text NOT NULL,
  "line" text NOT NULL,
  "state" text NOT NULL,
  "answer" text,
  "reason" text,
  "created_at" bigint NOT NULL,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);

CREATE INDEX "relays_from" ON "relays" ("from_agent", "created_at");
CREATE INDEX "relays_to" ON "relays" ("to_agent", "created_at");
